package com.example.rokidkeyboardbridge;
public final class AvatarDirectorTest {
 static int n;static void ok(boolean b,String s){n++;if(!b)throw new AssertionError(s);}
 public static void main(String[] args){
  AvatarActionDirector d=new AvatarActionDirector();long first=d.begin("座って",1000);ok(d.pending(),"request is not rendering proof");d.passiveFrame(0,1100);ok(d.pending(),"standing cannot acknowledge seated request");long second=d.begin("立って",1200);ok(!d.current(first)&&d.current(second),"newest instruction invalidates old decode");d.frame(0,1300);ok(!d.pending()&&d.label(1301).contains("表示しました"),"actual matching draw confirms");ok(d.label(4000).isEmpty(),"receipt expires");
  d.begin("手を振って",5000);d.passiveFrame(0,5100);ok(d.pending(),"ordinary fallback does not confirm requested gesture");d.frame(0,5200);ok(!d.pending(),"gesture draw confirms");d.begin("ねそべって",10000);ok(!d.recovery(15999),"bounded wait");ok(d.recovery(16000),"one controlled recovery");d.retry(16001);ok(!d.recovery(40000)&&d.failed(),"no endless reload loop");d.retry(41000,true);d.frame(2,41010);ok(!d.failed(),"manual recovery can finish");d.begin("座って",50000);d.stop(50001);ok(!d.pending()&&!d.current(second),"stop cancels immediately");
  for(String q:new String[]{"立って","ロキ、座って","ねそべって"})ok(AvatarActionDirector.posture(q)>=0,"local posture request");for(String q:new String[]{"立ってとは？","彼女が座ってと言った","座らないで"})ok(AvatarActionDirector.posture(q)==-1,"not a posture command");ok(AvatarActionDirector.stop("動きを止めて")&&!AvatarActionDirector.stop("音楽を止めて"),"visual stop is specific");
  EmbodiedScenePolicy p=new EmbodiedScenePolicy();p.user("ねそべって",1000);p.user("手を振って",2000);p.stopMotion(2100);ok(p.correctedRest()&&p.restMotion(2200)==0,"stopping lying wave keeps lying posture");p.answer("困りました。",FullBodyPoseCatalog.Kind.WORRY,3000);ok(p.correctedRest(),"emotion preserves posture");p.answer("お断りします。",FullBodyPoseCatalog.Kind.REFUSE,4000);ok(!p.correctedRest()&&p.safeRestHold()&&!p.canReplay(),"old acting ends, neutral lying remains");p.user("立って",5000);ok(!p.safeRestHold()&&p.posture()==0,"new posture replaces neutral hold");
  CharacterRenderBudget.reset();for(int i=0;i<3;i++)CharacterRenderBudget.sample(1000+i,60000000);ok(CharacterRenderBudget.quality==1,"render overload reduces detail");for(int i=0;i<3;i++)CharacterRenderBudget.sample(2000+i,95000000);ok(CharacterRenderBudget.quality==2&&CharacterRenderBudget.delay(33)==125,"severe overload saves cadence");for(int i=0;i<50;i++)CharacterRenderBudget.sample(2500+i,1000000);ok(CharacterRenderBudget.quality==2,"no rapid quality oscillation");for(int i=0;i<25;i++)CharacterRenderBudget.sample(13000+i,1000000);ok(CharacterRenderBudget.quality==1,"quality recovers with hysteresis");CharacterRenderBudget.reset();
  for(FullBodyPoseCatalog.Kind k:FullBodyPoseCatalog.Kind.values()){ok(!CharacterChoreography.optionalAllowed(true,false,false,k),"navigation outranks automatic motion");ok(!CharacterChoreography.optionalAllowed(false,true,false,k),"manual request outranks optional motion");if(ConversationVisualCatalog.restReaction(k)==RestConversationReaction.CARE)ok(!CharacterChoreography.optionalAllowed(false,false,false,k),"face and body agree on concern");}
  CharacterChoreography.update(false,true,false,false,false,1000);ok(CharacterChoreography.phase==CharacterChoreography.LISTEN,"recording phase");CharacterChoreography.update(false,false,false,true,false,2000);ok(CharacterChoreography.phase==CharacterChoreography.THINK,"AI pending phase");CharacterChoreography.clarify(3000);ok(CharacterChoreography.clarifying(3100),"clarification is distinct and finite");ok(!CharacterChoreography.clarifying(5700),"clarification ends");CharacterChoreography.update(true,false,false,false,false,6000);ok(CharacterChoreography.gain==0,"navigation preference default quiet");
  CharacterPerformance perf=new CharacterPerformance();perf.answer("要点です。次に説明します。最後に戻ります。");perf.mode(1000,2);boolean phrase=false;for(long now=1000;now<6000;now+=50)phrase|=perf.beat(now)>=0;ok(phrase,"punctuation creates speech beats");perf.mode(6500,0);ok(perf.finishing(7000),"speech has settling phase");ok(!perf.finishing(9000),"settling ends");ok(CharacterChoreography.lead(100)>0&&CharacterChoreography.lead(700)==0,"gaze leads and stops");
  CharacterChoreography.phase=CharacterChoreography.IDLE;CharacterChoreography.scene=0;CharacterChoreography.gain=1;CharacterRenderBudget.reset();System.out.println("PASS "+n+" latest-command, render receipt, posture, priority, load and choreography checks");
 }
}
